import java.io.* ;
import java.util.*;

public class ghh {

    static int n ;
    static long[] occ ;
    static long[] nbr_vertexes ;
    static long big = (long) (1e9 + 7) ;

    static void count_vertexes() {
        occ[0]++;
        nbr_vertexes[0] = 1;
        for (int i = 1; i <= n; i++) {
            long[] oc = new long[n / 2 + 1];
            int limite = Math.min(n - i, n / 2);
            for (int j = 0; j <= limite; j++) {
                long h = occ[j];
                if (j + 1 <= limite) {
                    oc[j + 1] = (oc[j + 1] + h) % big;
                }
                if (j - 1 >= 0) {
                    oc[j - 1] = (oc[j - 1] + h) % big;
                }
                oc[j] = (oc[j] + h) % big;
            }
            if (limite + 1 <= n / 2) {
                oc[limite] = (oc[limite] + occ[limite + 1]) % big;
            }
            long sum = 0;
            for (int j = 0; j <= limite; j++) {
                sum += oc[j];
                sum %= big;
                occ[j] = oc[j];
            }
            nbr_vertexes[i] = sum;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
        String line = br.readLine();
        int inputN = Integer.parseInt(line.trim());
        n = inputN * 2;
        occ = new long[n / 2 + 1];
        nbr_vertexes = new long[n + 1];
        long resA = 0, resB = 0;
        count_vertexes();
        for (int i = n - 1; i >= 0; i -= 2) {
            resA += nbr_vertexes[i];
            resA %= big;
        }
        for (int i = n - 2; i >= 0; i -= 2) {
            resB += nbr_vertexes[i];
            resB %= big;
        }
        pw.println(resA);
        pw.flush();
    }
}
